SELECT
    dsi.parent_category_name AS classify,
    SUM(doit.quantity) AS salesQuantity,
    SUM(doi.order_fee) AS sales,
    SUM(droit.quantity) AS returnOrderQty,
    SUM(droi.order_fee) AS returnOrderAmount,
    SUM(drit.quantity) AS refundOrderQty,
    SUM(dri.refund_amount) AS refundAmount,
    round(round(SUM(droit.quantity)::numeric,2) / round(SUM(doit.quantity)::numeric,2) * 100,2) AS refundOrderRate,
    round(round(SUM(drit.quantity)::numeric,2) / round(SUM(doit.quantity)::numeric,2) * 100,2) AS refundRate
FROM dmp_order_info doi
INNER JOIN dmp_order_item doit ON doi."id" = doit.order_id
LEFT JOIN dmp_return_order_info droi ON droi.platform_order_id = doi.platform_order_id
LEFT JOIN dmp_return_order_item droit ON droit.return_order_id = droi."id"
LEFT JOIN dmp_refund_info dri ON dri.platform_order_id = doi.platform_order_id
LEFT JOIN dmp_refund_item drit ON drit.refund_id = dri."id"
LEFT JOIN dmp_sku_info dsi ON dsi.sku_no = doit.sku_no



            AND doi.platform_create_time >= #{params.startTime}


            AND doi.platform_create_time <= #{params.endTime}




            AND doi.delivery_time >= #{params.startTime}


            AND doi.delivery_time <= #{params.endTime}





        AND doi.dept_id IN

            #{deptId}




        AND doi.source_platform IN

            #{platform}




        AND doi.site IN

            #{site}





        AND doi.shop_no IN

            #{shopNo}





        AND poit.sku_no IN

            #{sku}




        AND dsi.parent_category_name IN

            #{category}




        AND dsi.brand_id IN

            #{brand}





        AND doi.charge_id IN

            #{userId}




        #{params.permissionSql}



GROUP BY dsi.parent_category_name

